import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, float, vec3, mix, add } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, AmbientLight, DirectionalLight } = ctx.THREE;

  const root = new Group();

  // ---------- Background Gradient Plane ----------
  const BG_WIDTH = 7;
  const BG_HEIGHT = 6;
  const bgGeom = new PlaneGeometry(BG_WIDTH, BG_HEIGHT);
  const bgMat = new MeshStandardNodeMaterial();
  bgMat.transparent = true;
  const uvNode = uv();
  const yNode = uvNode.y;
  // Gradient stops from spec (fallback to simple black->surface)
  const gradStart = vec3(0x00 / 255, 0x00 / 255, 0x00 / 255); // transparent black (color part)
  const gradEnd = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255); // surface color
  bgMat.colorNode = mix(gradStart, gradEnd, yNode);
  const bgPlane = new Mesh(bgGeom, bgMat);
  bgPlane.position.set(0, 0, -2.5);
  root.add(bgPlane);

  // ---------- Lighting ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 1, 2).normalize();
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-1, -0.5, 2).normalize();
  root.add(ambient, keyLight, rimLight);

  // ---------- Photo Plane ----------
  const PLANE_W = 4.0;
  const PLANE_H = 2.5;
  const planeGeom = new PlaneGeometry(PLANE_W, PLANE_H, 64, 64);
  const planeMat = new MeshStandardNodeMaterial();
  planeMat.transparent = true;
  planeMat.opacity = 0; // start invisible
  planeMat.roughness = 0.6;
  planeMat.metalness = 0.0;
  const photoPlane = new Mesh(planeGeom, planeMat);
  root.add(photoPlane);

  // ---------- Load Textures ----------
  let imageTex, depthTex;
  ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
    imageTex = t;
    updateMaterial();
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((t) => {
    depthTex = t;
    updateMaterial();
  });

  function updateMaterial() {
    if (!imageTex || !depthTex) return;
    const colorNode = texture(imageTex);
    const dispTex = texture(depthTex);
    const displacementNode = mul(dispTex.r, float(0.18));
    // Simple filmic grade approximation (lift blacks, shift highlights)
    const lifted = add(colorNode, vec3(0.04, 0.04, 0.04)); // lift
    const graded = mix(lifted, vec3(0xe8 / 255, 0xec / 255, 0xf2 / 255), float(0.12)); // highlight tint
    planeMat.colorNode = graded;
    planeMat.displacementNode = displacementNode;
    planeMat.needsUpdate = true;
  }

  // ---------- Caption Block ----------
  const captionGroup = new Group();
  const PAD = 0.5; // 2 × base unit (0.25)
  const startX = -PLANE_W / 2 + PAD;
  const startY = -PLANE_H / 2 + PAD;
  captionGroup.position.set(startX, startY + 0.4, 0.01);
  root.add(captionGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const lineSpacing = 0.25;
  let cursorY = 0;

  const colors = config.visualSpec?.colors ?? {};
  const inkColor = colors.ink ?? '#16161d';
  const paperColor = colors.paper ?? '#e8ecf2';
  const accentColor = colors.accent ?? '#ff2a38';

  for (const item of items) {
    const role = item.role ?? '';
    const txt = ctx.fontAtlas.createText(item.text ?? item.content ?? '', {
      fontSize: item.typography?.fontSize ?? 13,
      color: role === 'kicker' ? inkColor : paperColor,
      align: 'left',
    });
    txt.position.set(0, -cursorY, 0);
    captionGroup.add(txt);
    cursorY += lineSpacing;

    if (role === 'headline') {
      const barGeom = new PlaneGeometry(0.75, 0.02);
      const barMat = new MeshStandardNodeMaterial({
        color: accentColor,
        emissive: accentColor,
        emissiveIntensity: 1.8,
        roughness: 0.5,
        metalness: 0.0,
        transparent: false,
      });
      const bar = new Mesh(barGeom, barMat);
      bar.position.set(0, -cursorY + 0.1, 0);
      captionGroup.add(bar);
    }
  }

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(photoPlane, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // ---------- Animations ----------
  const tl = gsap.timeline();
  tl.to(
    planeMat,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate: () => {
        planeMat.needsUpdate = true;
      },
    },
  );
  tl.to(
    captionGroup.position,
    {
      y: startY,
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      delay: 0.12,
    },
    '<',
  );

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    planeGeom.dispose();
    planeMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    if (imageTex) imageTex.dispose();
    if (depthTex) depthTex.dispose();
    // Dispose caption resources
    captionGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry && obj.geometry.dispose();
        obj.material && obj.material.dispose();
      }
    });
    // Dispose lights
    ambient.dispose();
    keyLight.dispose();
    rimLight.dispose();
  };

  return root;
}
